={{
JSON.stringify({
  query: `query GetOrders($query: String!, $cursor: String) {
    orders(
      first: 10
      after: $cursor
      query: $query
      sortKey: CREATED_AT
      reverse: true
    ) {
      nodes {
        id
        name
        createdAt
        totalPriceSet {
          shopMoney {
            amount
            currencyCode
          }
        }
        displayFinancialStatus
        cancelledAt
        cancelReason
        lineItems(first: 100) {
          nodes {
            quantity
            product {
              id
              title
            }
          }
        }
      }

      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }`,
  variables: {
  query: `created_at:>='${$json.startOfDay}' AND created_at:<'${$json.endOfDay}'`,
  cursor: $json.cursor || null
}
})
}}

parameters.jsCode:
const shopify = $('Shopify - Get Orders').all();

const allOrders = [];

for (const item of shopify) {
  const orders = item.json.data?.orders?.nodes || [];
  allOrders.push(...orders);
}

const latestShopify = shopify[shopify.length - 1]?.json;
const ordersData = latestShopify?.data?.orders;

if (!ordersData) {
  throw new Error('Shopify orders data not found.');
}

return [
  {
    json: {
      allOrders,
      totalAccumulatedOrders: allOrders.length,

      hasNextPage: ordersData.pageInfo?.hasNextPage || false,

      endCursor: ordersData.pageInfo?.endCursor || null
    }
  }
];

const data = $input.first().json;

return [
  {
    json: {
      reportDate: data.reportDate,
      startOfDay: data.startOfDay,
      endOfDay: data.endOfDay,

      allOrders: [],

      cursor: null,
      hasNextPage: true
    }
  }
];

const data = $input.first().json;

const allOrders = data.allOrders || [];

return [
  {
    json: {
      reportDate: data.reportDate,
      startOfDay: data.startOfDay,
      endOfDay: data.endOfDay,

      totalOrders: allOrders.length,

      orders: allOrders
    }
  }
];

const now = new Date();

const pakistanDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Karachi',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(now);

const [year, month, day] = pakistanDate.split('-');

// Pakistan midnight at the beginning of the reporting day
const startPakistan = new Date(
  `${year}-${month}-${day}T00:00:00+05:00`
);

// Pakistan midnight at the beginning of the next day
const endPakistan = new Date(startPakistan);
endPakistan.setUTCDate(endPakistan.getUTCDate() + 1);

// Remove milliseconds because Shopify's search timestamp
// works better with second-precision ISO timestamps.
const startOfDay = startPakistan
  .toISOString()
  .replace('.000Z', 'Z');

const endOfDay = endPakistan
  .toISOString()
  .replace('.000Z', 'Z');

return [
  {
    json: {
      reportDate: pakistanDate,
      startOfDay,
      endOfDay
    }
  }
];

const page = $('Process Shopify Page').first().json;

return [
  {
    json: {
      reportDate: $('Initialize Pagination').first().json.reportDate,
      startOfDay: $('Initialize Pagination').first().json.startOfDay,
      endOfDay: $('Initialize Pagination').first().json.endOfDay,

      cursor: page.endCursor
    }
  }
];

const orders = $json.orders || [];

let totalOrders = orders.length;
let totalRevenue = 0;
let paidOrders = 0;
let cancelledOrders = 0;
let refundedOrders = 0;

const productSales = {};

for (const order of orders) {

  // Revenue
  const amount = parseFloat(
    order.totalPriceSet?.shopMoney?.amount || 0
  );

  totalRevenue += amount;

  // Financial status
  const financialStatus =
    order.displayFinancialStatus || '';

  if (financialStatus === 'PAID') {
    paidOrders++;
  }

  if (order.cancelledAt) {
    cancelledOrders++;
  }

  if (
    financialStatus === 'REFUNDED' ||
    financialStatus === 'PARTIALLY_REFUNDED'
  ) {
    refundedOrders++;
  }

  // Products
  const lineItems = order.lineItems?.nodes || [];

  for (const item of lineItems) {

    const productTitle =
      item.product?.title || 'Unknown Product';

    const quantity =
      Number(item.quantity || 0);

    productSales[productTitle] =
      (productSales[productTitle] || 0) + quantity;
  }
}

// Average Order Value
const averageOrderValue =
  totalOrders > 0
    ? totalRevenue / totalOrders
    : 0;

// Find top product
let topProduct = 'N/A';
let topProductQuantity = 0;

for (const [product, quantity] of Object.entries(productSales)) {

  if (quantity > topProductQuantity) {
    topProduct = product;
    topProductQuantity = quantity;
  }
}

return [
  {
    json: {
      totalOrders,
      totalRevenue: Number(totalRevenue.toFixed(2)),
      averageOrderValue: Number(averageOrderValue.toFixed(2)),

      paidOrders,
      cancelledOrders,
      refundedOrders,

      topProduct,
      topProductQuantity
    }
  }
];

const data = $json;

const reportDate = $('Prepare Report Date').first().json.reportDate;

const currency = 'USD';

const report = `DAILY SALES REPORT
â”â”â”â”â”â”â”â”â”â”â”â”â”â”â”â”â”â”â”â”

Date: ${reportDate}

Orders: ${data.totalOrders}
Revenue: ${currency} ${data.totalRevenue.toFixed(2)}
Average Order Value: ${currency} ${data.averageOrderValue.toFixed(2)}

Paid Orders: ${data.paidOrders}
Cancelled: ${data.cancelledOrders}
Refunded: ${data.refundedOrders}

Top Product:
${data.topProduct} (${data.topProductQuantity} units)
`;

return [
  {
    json: {
      reportDate,
      totalOrders: data.totalOrders,
      totalRevenue: data.totalRevenue,
      averageOrderValue: data.averageOrderValue,
      paidOrders: data.paidOrders,
      cancelledOrders: data.cancelledOrders,
      refundedOrders: data.refundedOrders,
      topProduct: data.topProduct,
      topProductQuantity: data.topProductQuantity,
      currency,
      report
    }
  }
];
